    for n in nums:
        if n == c1: n1 += 1
        elif n == c2: n2 += 1
        elif n1 == 0: c1, n1 = n, 1
        elif n2 == 0: c2, n2 = n, 1
        else: n1 -= 1; n2 -= 1
