def findAnagrams(s, p):
    if len(p) > len(s): return []
    cp, cs = {}, {}
    for ch in p: cp[ch] = cp.get(ch, 0) + 1
    k = len(p)
    res = []
    for i in range(len(s)):
        cs[s[i]] = cs.get(s[i], 0) + 1
        if i >= k:
            old = s[i - k]
            if cs[old] == 1: del cs[old]
            else: cs[old] -= 1
        if cs == cp: res.append(i - k + 1)
    return res

