def subarraysWithKDistinct(nums, k):
    def atMost(k_val):
        count = {}
        l = 0
        ans = 0
        for r in range(len(nums)):
            count[nums[r]] = count.get(nums[r], 0) + 1
            while len(count) > k_val:
                count[nums[l]] -= 1
                if count[nums[l]] == 0: del count[nums[l]]
                l += 1
            ans += r - l + 1
        return ans
    return atMost(k) - atMost(k - 1)

