def carFleet(target, position, speed):
    pair = [[p, s] for p, s in zip(position, speed)]
    pair.sort(key=lambda x: x[0], reverse=True)
    stack = []
    for p, s in pair:
        time = (target - p) / s
        if not stack or time > stack[-1]:
            stack.append(time)
    return len(stack)

