def detectCycle(head):
    slow, fast = head, head
    while fast and fast.get("next"):
        slow = slow["next"]
        fast = fast["next"]["next"]
        if slow is fast:
            p = head
            while p is not slow:
                p = p["next"]
                slow = slow["next"]
