    for w in words:
        curr = trie
        for ch in w:
            if ch not in curr: curr[ch] = {}
            curr = curr[ch]
        curr["#"] = w
    res = set()
    def dfs(r, c, parent):
        ch = board[r][c]
        curr = parent[ch]
        if "#" in curr: res.add(curr["#"])
        board[r][c] = "#"
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(board) and 0 <= nc < len(board[0]) and board[nr][nc] in curr:
